create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, avatar_url text, role text not null default 'viewer' check (role in ('viewer','creator','rights_holder','moderator','finance','support','administrator','super_admin')), created_at timestamptz not null default timezone('utc', now()), updated_at timestamptz not null default timezone('utc', now())); alter table public.profiles enable row level security; create policy profiles_select_own on public.profiles for select to authenticated using (auth.uid() = id); create policy profiles_insert_own on public.profiles for insert to authenticated with check (auth.uid() = id); create policy profiles_update_own on public.profiles for update to authenticated using (auth.uid() = id) with check (auth.uid() = id); create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $function$ begin insert into public.profiles (id, display_name) values (new.id, coalesce(new.raw_user_meta_data ->> 'full_name', new.email)); return new; end; $function$; drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();